    ["the_deadmines"] = {
        { 92747, "A", 9, 16, "Alba Fairmoon", "Westfall 52.4,53", nil, false, {92745}, nil, "Collect 8 Suspicious Industrial Supplies from Moonbrook. The crates are not on the town streets — they are inside the building leading to the Deadmines entrance, down the path into the cave.", "毒素调查链的一环：几处矿井的样本都查过了，线索都指向月溪镇下方的死亡矿井。到月溪镇收集补给品，回阿尔巴·晴月处交任务后开启爆炸物筹备段。前导环《测井》的两个采样点：莫尔森农场 46.2,38.3、詹森农庄 56.7,18.7。◎ 补给箱就在通往死矿入口的洞穴里，月溪镇各建筑（包括月溪学校）里也散落着一些，不用打精英。", {{9,1}, {12,2}, {14,3}, {19,4}, {23,5}}, nil, nil, 253092, "Alba Fairmoon", { xp = 575, money = 400, rep = { {72, 50, "Stormwind City"} } } },
        { 92753, "A", 9, 18, "Alba Fairmoon", "Westfall 52.4,53", nil, false, {92752}, nil, "Find the furnace deep inside the Deadmines and place the Powerful Blasting Charge beside it; then rendezvous with Alba Fairmoon at the Deadmines exit.", "The dungeon segment of the chain: before entering, the explosives are already prepared by the materiel phase (Sprite Jumpsprocket → Jasper Fel). After planting them, exit the dungeon and meet Alba Fairmoon on the hill behind Moonbrook. ◎ The forge is the room where Gilnid spawns — plant the explosives near the center; after this run do NOT hearth out: leave through the back door and continue the quest at the back entrance.", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253092, "Alba Fairmoon", { xp = 4050, rep = { {72, 50, "Stormwind City"} } } },
        { 92819, "A", 9, 18, "Alba Fairmoon", "Westfall - the hill behind Moonbrook 38.6,83.2", "Destruction in Deadmines", false, {92753}, nil, "Use the remote detonator to set off the charge placed beside the furnace.", "《爆破死亡矿井》的收尾环：与月溪镇后方山丘的阿尔巴·晴月会合后，使用起爆器收尾。", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253279, "Alba Fairmoon", { xp = 140, rep = { {72, 50, "Stormwind City"} } } },
        { 166, "A", 14, 22, "Marshal Gryan Stoutmantle", "Westfall - Sentinel Hill 56,47", "Red Silk Bandanas", false, {155}, {6087, 2041, 2042}, "Kill Edwin VanCleef and bring his head back to Marshal Gryan Stoutmantle.", "整个系列从格里安·斯托曼(西部荒野-哨兵岭 56,47)开始。范克里夫是死亡矿井的最终 首领，在船的最上层。", {{14,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {3637}, nil, 234, "Marshal Gryan Stoutmantle", { xp = 2600, rep = { {72, 200, "Stormwind City"} } } },
        { 168, "A", 14, 18, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {2037, 2036, 270007}, "Collect 4 Miners' Union Membership Cards and bring them to Wilder Thistlenettle in Stormwind City.", "会员卡由副本入口附近的亡灵掉落。◎ 会员卡掉率很低且不共享（各拾各的），耗时会比较久。", {{14,2}, {16,3}, {21,4}, {25,5}}, {1894}, nil, 656, "Wilder Thistlenettle", { xp = 1350, rep = { {47, 100, "Ironforge"} } } },
        { 214, "A", 14, 17, "Scout Riell", "Westfall - Sentinel Hill 56, 47", "Red Silk Bandanas", false, {155}, {2074, 2089, 6094, 270005}, "Collect 10 Red Silk Bandanas and bring them to Scout Riell in the watchtower of Sentinel Hill.", "副本内外的矿工都会掉面罩。要先完成《护送迪菲亚叛徒》才会开放这个任务。", {{14,2}, {15,3}, {20,4}, {24,5}}, {915}, nil, 820, "Scout Riell", { xp = 1250, rep = { {72, 100, "Stormwind City"} } } },
        { 167, "A", 15, 20, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {1893, 270012, 270013}, "Retrieve the Explorer's League badge and bring it to Wilder Thistlenettle in Stormwind City.", "Badges drop from Foreman Thistlenettle right by the dungeon entrance. ◎ For solo runs wait until level 23 or so: the elites hit hard and chain-pull, and the quest mob is linked to another add.", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {1875}, nil, 656, "Wilder Thistlenettle", { xp = 1550, money = 500, rep = { {47, 100, "Ironforge"} } } },
        { 2040, "A", 15, 20, "Shoni the Shilent", "Stormwind City - Dwarven District 62,34", "Shoni the Shilent", false, {2041}, {7606, 7607, 270015, 270016}, "Retrieve the Compact High-Energy Engine from the Deadmines and bring it to Shoni the Shilent in the Dwarven District of Stormwind City.", "这个任务可以直接接，也可以先做诺恩(铁炉堡-侏儒区 69,50)给的引导任务。发动机由斯尼德的伐木机掉落。", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {7365}, nil, 6579, "Shoni the Shilent", { xp = 1550, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
        { 373, "A", 16, nil, nil, "The Unsent Letter drops from (Edwin VanCleef)", nil, true, nil, nil, "Search Edwin VanCleef's body for a letter that was never sent — it is addressed to Baros Alexston of the Stonemasons' Guild in Stormwind City.", "巴隆斯·阿历克斯顿(暴风城大教堂旁 58,49)。", {{16,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {2874}, nil, nil, nil, { xp = 2050, rep = { { 72, 50, "Stormwind City" } } } },
        { 1654, "A", 20, nil, "Jordan Stilwell", "Dun Morogh - Ironforge 52,36", "The Test of Righteousness", false, {1653}, nil, "Gather the materials on Jordan's weapon list — White Stone Oak, Refined Ore, Jordan's Hammer and the Kol Gem — and return to Jordan Stilwell in Ironforge.", "Click [Jordan's Weapon Materials List] to see the details.", {{20,3}, {25,4}, {29,5}}, {6994, 6993, 6895, 7083, 6996}, "Paladin", 6181, "Jordan Stilwell", nil },
    },
    ["shadowfang_keep"] = {
        { 1013, "H", 16, 26, "Keeper Bel'dugur", "Undercity - The Apothecarium 53,54", nil, false, nil, {6335, 4534, 270030}, "Bring the Book of Ur to Keeper Bel'dugur in the Apothecarium of the Undercity.", "The book is on the bookshelf in Fenrus' (the great worg) room — bottom shelf of the first bookcase on the left as you enter, a blue book. ◎ It respawns after about 10 seconds, so every party member can loot one (not shared). ◎ When Fenrus dies he summons 4 Voidwalkers (non-elite but they hit hard; rogues/cats can drop combat early with Vanish/Prowl).", {{16,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {6283}, nil, 2934, "Keeper Bel'dugur", { xp = 2100, money = 1400, rep = { {68, 100, "Undercity"} } } },
        { 1014, "H", 18, 27, "Dalar Dawnweaver", "Silverpine Forest - The Sepulcher 44,39", nil, false, nil, {6414}, "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", "Arugal is inside the dungeon.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5442}, nil, 1938, "Dalar Dawnweaver", { xp = 3300, rep = { {68, 200, "Undercity"} } } },
        { 1098, "H", 18, 25, "High Executor Hadrec", "Silverpine Forest - The Sepulcher 43,40", nil, false, nil, {3324, 270023, 270024}, "Find Sentinel Adamant and Sentinel Vincent.", "Deathstalker Adamant is inside the dungeon; Deathstalker Vincent is to the right after entering the courtyard. For the first part you must release the imprisoned deathstalker before the courtyard door opens; the second one can be seen tormented by Arugal right as you enter — work your way around to free him.", {{18,1}, {21,2}, {23,3}, {28,4}, {33,5}}, nil, nil, 1952, "High Executor Hadrec", { xp = 2000, money = 1800, rep = { {68, 100, "Undercity"} } } },
        { 1654, "A", 20, nil, "Jordan Stilwell", "Dun Morogh - Ironforge 52,36", "The Test of Righteousness", false, {1653}, nil, "Gather the materials on Jordan's weapon list — White Stone Oak, Refined Ore, Jordan's Hammer and the Kol Gem — and return to Jordan Stilwell in Ironforge.", "Click [Jordan's Weapon Materials List] to see the details.", {{20,3}, {25,4}, {29,5}}, {6994, 6993, 6895, 7083, 6996}, "Paladin", 6181, "Jordan Stilwell", { xp = 870 } },
        { 1740, nil, 20, nil, "Doan Karhan", "The Barrens 49,57", nil, false, nil, nil, "Collect 3 Shards of Solanruk's Orb and 1 Large Shard, and bring them to Duane Kahan in the Barrens.", "Warlock only! The shards drop from Twilight Acolytes in Blackfathom Deeps; the large shard drops from the Shadowfang Moonrunner wolves in Shadowfang Keep.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {6914, 6915}, "Warlock", 6247, "Doan Karhan", nil },
    },
    ["excavation_wetlands"] = {
        { 95772, "A", 24, 31, "多林·桑布雷德", "Redridge Mountains - Lakeshire 25.6,46.6", nil, false, nil, nil, "到维尔加挖掘场一带寻找多林·桑布雷德的兄弟戴温。", "戴温随勘探队进了挖掘场，之后能在副本内他的遗体上接到后续任务。◎ 发布者在湖畔镇的马厩里——从飞行点过桥后左手边。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 956, "多林·桑布雷德", { xp = 3150 } },
        { 98815, "A", 24, 28, "詹姆斯·哈洛兰", "Wetlands - 米奈希尔港 8,55", "日常供货", false, {469}, nil, "把 4 张灌木丛迅猛龙皮交给米奈希尔港的制皮匠詹姆斯·哈洛兰。", "迅猛龙皮由挖掘场的迅猛龙类掉落；前置是哈洛兰的《幼鳄鱼皮》，无需先做《日常供货》。", {{24,2}, {26,3}, {31,4}, {36,5}}, nil, nil, 2094, "詹姆斯·哈洛兰", { xp = 1150, money = 1200, rep = { {72, 50, "Stormwind City"} } } },
        { 95646, "A", 24, 31, "绿色守卫者雷希耶尔", "Wetlands 56.2,40.6", nil, false, nil, {271667, 271670, 271664}, "在挖掘场杀一只高地惊魂，把它的根核带给湿地的雷希耶尔。", "The Dreadful Root Core drops from Highland Terrors inside the dungeon. ◎ Prerequisite: finish First Mate Fitzsimmons' four-step Wetlands chain — The Greenwarden, Tramping Paws, Fire Taboo, Blisters on The Land — before this quest is offered.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270180}, nil, 1244, "绿色守卫者雷希耶尔", { xp = 3150 } },
        { 95647, "A", 24, 31, "凯特林·格拉斯曼", "Wetlands - 米奈希尔港南 11.6,58.4", "寻找凯特林", false, {95737}, nil, "在挖掘场找到阿尔丁·格拉斯曼，弄清他遭遇了什么。", "链从蓝纳(灰谷 35.0,48.6)的《寻找凯特林》开始。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 1480, "凯特林·格拉斯曼", { xp = 2500 } },
        { 95795, "A", 24, 31, nil, nil, nil, true, nil, {271769, 271768}, "把戴温的命运带回湖畔镇告诉多林·桑布雷德。", "Starts on Dewin's corpse inside the dungeon.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, nil, nil, { xp = 3150 } },
        { 95697, "H", 24, 31, "博斯坦", "Orgrimmar - The Drag 57.5,53.4", nil, false, nil, {280766, 280805, 250185, 250077}, "进挖掘场带回 4 块灌木丛迅猛龙肉。", "肉由副本内迅猛龙类掉落；发布者=烹饪训练师博斯坦(奥格瑞玛暗巷区 57.5,53.4)。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {271100}, nil, 3368, "博斯坦", { xp = 3150 } },
        { 95664, "H", 24, 31, nil, nil, nil, true, nil, nil, "把泰坦圣物带到雷霆崖长者高地，找能鉴定它的人。", "打完尾王遗迹守卫者后拾取泰坦圣物，拾取即开启本任务；上交时泰坦圣物不会归还。", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95810, "A", 24, 31, nil, nil, nil, true, nil, nil, "把泰坦圣物带给湿地的勘察员维尔加。", "Started by looting the Titan Relic; the Alliance turn-in is Prospector Whelgar at Whelgar's Excavation Site.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95682, "H", 24, nil, "Deathstalker Agent", "Wetlands - 挖掘场入口旁的山丘 51.4,59.2", nil, false, {95663}, {271740, 271732, 271745}, "在挖掘场杀 2 名龙喉破坏者和 4 名龙喉守卫，带着战利品回到副本外的亡灵卫兵密探处。", "龙喉急件由副本内龙喉单位掉落；发布者藏在入口区域旁的山丘里。◎ 前置可在落锤镇楼梯下的兽人处接取。", nil, {284844}, nil, 13155, "Deathstalker Agent", { xp = 6950 }},
        { 98823, "H", 24, nil, nil, nil, "长者知识", false, {95664}, {271766, 271767, 271719}, "把泰坦圣物带给莫高雷西北天空守望者高地的穆恩·大地之怒（Muln Earthfury）。", "《长者知识》的后续；圣物由尾王遗迹守卫者掉落。◎ 上交《长者知识》时圣物会被吞、本任务无法完成，弃任务后也无法重接。", nil, {270865}, nil, nil, nil, { xp = 6950 } },
        { 95809, "A", 24, nil, nil, nil, "灌木丛里的东西", false, {95647}, {1710, 3827, 2459, 280766}, "把编草心带回米奈希尔港交给凯特林·格拉斯曼。", "完成《灌木丛里的东西》后阿尔丁给的信物编草心（Reed-woven Heart）开启本任务。", nil, {270901}, nil, nil, nil, { xp = 6150 } },
        { 98824, "A", 24, nil, "勘察员维尔加", nil, "运送失落的圣物", false, {95810}, {271716, 271767, 271766}, "把泰坦圣物带给铁炉堡探险者大厅的高级探险家玛盖拉斯（High Explorer Magellas）。", "《运送失落的圣物》的后续，在勘察员维尔加处接续；圣物由尾王遗迹守卫者掉落。◎ 同系问题：上交前一步会丢失泰坦圣物，导致无法交付。", nil, {270865}, nil, 1077, "勘察员维尔加", { xp = 6150 } },
    },
    ["blackfathom_deeps"] = {
        { 971, "A", 18, 23, "Gerrig Bonegrip", "Ironforge - The Forlorn Cavern 50,5", nil, false, nil, {6743}, "Bring the Lorgalis Manuscript to Gerrig Bonegrip in Ironforge.", "The manuscript lies in a pool inside the dungeon — in the water area of the turtle-king room: an underwater alcove chest on the right as you enter, guarded by 1-2 naga (single-pullable).", {{18,1}, {19,2}, {21,3}, {26,4}, {31,5}}, {5359}, nil, 2786, "Gerrig Bonegrip", { xp = 2750, rep = { {47, 50, "Ironforge"} } } },
        { 6563, "H", 17, 22, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", "The Essence of Aku'Mai", false, {6562}, nil, "Collect 20 Aku'mai Sapphires and bring them to Je'neu Sancrea in Ashenvale.", "前置《帮助耶努萨克雷》可在苏纳曼(石爪山脉-烈日石居 47,64)接。蓝宝石长在通往黑暗深渊入口那条通道的洞壁上。", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16784}, nil, 12736, "Je'neu Sancrea", { xp = 1750, money = 1400, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 6564, "H", 17, 22, "A Damp Note", "Drops - see notes", nil, false, nil, nil, "Deliver the Damp Note to Je'neu Sancrea in Ashenvale; then kill Lorgus Jett in Blackfathom Deeps and report back.", "需要先接取《阿库麦尔水晶》，才会掉落|cff999999(Coupdegrace反馈)|r。便笺由黑暗深渊副本门口的海潮祭司掉落（约5%）。耶努萨克雷(灰谷-佐拉姆加前哨站 11,33)。洛古斯·杰特(副本内)。", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16790}, nil, nil, nil, { xp = 1300, money = 1100, rep = { {530, 75, "Darkspear Trolls"} } } },
        { 6565, "H", 17, 26, "Je'neu Sancrea", "Ashenvale", nil, false, {6564}, {17694, 17695}, nil, nil, {{17,1}, {22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 12736, "Je'neu Sancrea", { xp = 2650, money = 4000, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 1198, "A", 18, nil, "Dawnwatcher Shaedlass", "Darnassus - Craftsmen's Terrace 55,24", nil, false, nil, nil, "Enter Blackfathom Deeps and find Argent Guard Thaelrid.", "塞尔瑞德在副本内。塞尔瑞德在海龟池西南侧的水下。起始 NPC 在联盟主城达纳苏斯，部落接这个任务得死很多次。", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, nil, nil, 4786, "Dawnwatcher Shaedlass", { xp = 5700, rep = { { 529, 150, "Argent Dawn" }, { 69, 150, "Darnassus" } } } },
        { 1200, "A", 18, 27, "Argent Guard Thaelrid", "Blackfathom Deeps", "Blackfathom Villainy", true, {1198}, {7001, 7002, 270031, 270032}, "Retrieve the head of Sleepwalker Kerlis and bring it to Sentinel Selgolm in Darnassus.", "克尔里斯在副本内；塞尔高姆(达纳苏斯-工匠区 55,24)。小心：点燃克尔里斯旁边的火焰会触发敌人增援。", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {69, 200, "Darnassus"} } } },
        { 1275, "A", 18, 24, "Gershala Nightwhisper", "Darkshore - Auberdine 38,43", "Researching the Corruption", false, {3765}, {7003, 7004, 270021}, "Collect 8 Corrupted Brainstems for Gershala Nightwhisper in Auberdine.", "前置可找阿古斯·夜语接(暴风城-花园 36,67)。副本内外所有纳迦都掉脑干。", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, {5952}, nil, 8997, "Gershala Nightwhisper", { xp = 2400, money = 3500, rep = { {69, 150, "Darnassus"} } } },
        { 6561, "H", 18, 27, "Scout Thaelrid", "Blackfathom Deeps", nil, true, nil, {7001, 7002, 270031, 270032}, "Bring the head of Sleepwalker Kerlis back to Bashana Runetotem in Thunder Bluff.", "克尔里斯在副本内；巴珊娜·符文图腾(雷霆崖-长者高地 70,33)。小心：点燃克尔里斯身旁的火焰会引来敌人。", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {81, 200, "Thunder Bluff"} } } },
        { 1199, "A", 20, 25, "Argent Guard Manados", "Darnassus - Craftsmen's Terrace 55,23", nil, false, nil, {6998, 7000, 270025}, "Collect 10 Twilight Pendants and bring them to Argent Guard Manados in Darnassus.", "暮光之锤的敌人个个都掉坠饰。◎ 当前版本结算会把 3 件奖励一起给。", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {5879}, nil, 4784, "Argent Guard Manados", { xp = 2550, rep = { {529, 150, "Argent Dawn"}, {69, 150, "Darnassus"} } } },
        { 1740, nil, 20, nil, "Doan Karhan", "The Barrens 49,57", nil, false, nil, { 6898, 15109 }, "Collect 3 Shards of Solanruk's Orb and 1 Large Shard, and bring them to Duane Kahan in the Barrens.", "Warlock only! The shards drop from Twilight Acolytes in Blackfathom Deeps; the large shard drops from the Shadowfang Moonrunner wolves in Shadowfang Keep.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {6914, 6915}, "Warlock", 6247, "Doan Karhan", { xp = 5100 } },
        { 6921, "H", 21, 27, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", nil, false, nil, nil, "Bring the Core of the Deeps to Je'neu Sancrea at Zoram'gar Outpost in Ashenvale.", "The Fathom Core is in the water inside the dungeon. Once you take it, Baron Aquanis will appear and attack — he drops a quest item; bring that to Je'neu Sancrea as well. The core is underwater in the center of the big pool before the last boss (no need to enter the boss's room).", {{21,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {16762}, nil, 12736, "Je'neu Sancrea", { xp = 2750, money = 4500, rep = { {530, 150, "Darkspear Trolls"} } } },
    },
    ["the_stockade"] = {
        { 391, "A", 16, 29, "Warden Thelwater", "Stormwind City - The Stockade 51,69", "The Stockade Riots", false, {389}, nil, "Kill Bazil Thredd and bring his head to Warden Thelwater.", "前置见死亡矿井的《迪菲亚兄弟会》系列。巴基尔·斯瑞德在副本内。", {{16,1}, {25,2}, {27,3}, {32,4}, {37,5}}, {2926}, nil, 1719, "Warden Thelwater", { xp = 2350, money = 2500, rep = { {72, 100, "Stormwind City"} } } },
        { 377, "A", 22, 26, "Councilman Millstipe", "Duskwood - Darkshire 72,47", nil, false, nil, {2033, 2906}, "Kill Dexter Ward and bring his hand back to Councilman Millstipe of Darkshire as proof.", "Dexter Ward is inside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, {3628}, nil, 270, "Councilman Millstipe", { xp = 2100, rep = { {72, 100, "Stormwind City"} } } },
        { 378, "A", 22, 27, "Motley Garmason", "Wetlands - Dun Modr 49,18", "The Fury Runs Deep", false, {303}, {3562, 1264}, "Bring the head of Kam Deepfury to Motley Garmason in Dun Modr.", "The prerequisite is also taken from Motley Garmason. Kam Deepfury is inside the dungeon.", {{22,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {3640}, nil, 1074, "Motley Garmason", { xp = 2750, rep = { {47, 150, "Ironforge"} } } },
        { 386, "A", 22, 25, "Guard Berton", "Redridge Mountains - Lakeshire 26,46", nil, false, nil, {3400, 1317}, "Bring the head of Targorr to Guard Berton in Lakeshire.", "Targorr is inside the dungeon. He usually spawns in the first cell on the right or the second cell on the left of the central wing; rarely, in the northernmost cell between the two wings.", {{22,2}, {23,3}, {28,4}, {33,5}}, {3630}, nil, 859, "Guard Berton", { xp = 2000, rep = { {72, 100, "Stormwind City"} } } },
        { 387, "A", 22, 26, "Warden Thelwater", "Stormwind City - The Stockade 51,69", nil, false, nil, nil, "Take stock of the Stockade for Warden Thelwater of Stormwind: kill 10 Defias Convicts, 8 Defias Criminals and 8 Defias Insurgents.", "The quest is issued by the warden outside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 1719, "Warden Thelwater", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
        { 388, "A", 22, 26, "Nikova Raskol", "Stormwind City - Old Town 75,63", nil, false, nil, nil, "Collect 10 Red Wool Bandanas and bring them to Nikova Raskol in Stormwind City.", "Nikova Raskov wanders around Old Town; nearly every enemy in the Stockade drops a mask.", {{22,2}, {24,3}, {29,4}, {34,5}}, {2909}, nil, 1721, "Nikova Raskol", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
    },
    ["city_of_dalaran"] = {
        { 92457, "A", 24, 33, "Image of Archmage Modera", "Alterac Mountains - outside the City of Dalaran entrance", nil, false, nil, {279837, 279838}, "For Archmage Modera outside Dalaran, defeat 8 Seeking Remnants, 8 Saturated Remnants and 8 Mana Echoes inside the City of Dalaran.", "起始在副本外（大法师莫德拉的影像），开始并结束于同处。三种奥术元素怪都在达拉然城内：觅索残迹、饱和残迹、法力回响。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 269127, "Image of Archmage Modera", { xp = 9400, rep = { {2740, 100, "Kirin Tor"} } } },
        { 92489, "A", 24, 33, "High Sorcerer Andromath", "Stormwind City - Mage Quarter", nil, false, nil, {251962, 279849}, "替暴风城的高阶巫师安多玛斯，消灭达拉然城内的奥术之谜（Arcanic Enigma）。", "起始并结束于暴风城法师区的高阶巫师安多玛斯。奥术之谜是复苏之路上的精英怪，会沉默 10 秒并召唤奥术法力苗。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5694, "High Sorcerer Andromath", { xp = 9400 } },
        { 92432, "A", 30, 33, "Emissary Jacques", "Hillsbrad Foothills - Southshore 48.3,60.1", "紧急求援", false, nil, nil, "向达拉然城附近的大法师莫德拉的影像汇报。", "在希尔斯布莱德丘陵南海镇的使者雅克处接取（可共享）。联盟链：紧急求援（使者雅克→莫德拉的影像）→ 动乱之源（莫德拉的影像处接取，进城收集奥术微粒，自动发放「达拉然下水道钥匙」）→ 肯瑞托之友（莫德拉的影像处接取，交付给紫罗兰城堡的大法师塞林德拉）。", {{30,1}, {31,2}, {36,3}, {42,4}}, nil, nil, 247264, "Emissary Jacques", { xp = 660, rep = { { 2740, 10, "Kirin Tor" } } }},
        { 92458, "A", 24, 33, "Image of Archmage Modera", "Silverpine Forest - 达拉然城副本外", "动乱之源", false, {92432}, {279839, 279840, 279841}, "Recover the Arcane Mote inside the City of Dalaran for the Image of Archmage Modera outside the city.", "接取并交付都在副本外的大法师莫德拉的影像。联盟链：紧急求援（南海镇使者雅克接取，汇报到莫德拉的影像处）→ 本任务（进城收集奥术微粒）→ 肯瑞托之友（莫德拉的影像处接取，交付给紫罗兰城堡的大法师塞林德拉）。接本任务即自动发放「达拉然下水道钥匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "Image of Archmage Modera", { xp = 9400, rep = { {2740, 100, "Kirin Tor"} } } },
        { 92459, "A", 24, 33, "Image of Archmage Modera", "Silverpine Forest - 达拉然城副本外", "肯瑞托之友", false, {92458}, nil, "带着奥术微粒回到达拉然城，与大法师塞林德拉谈谈。", "在大法师莫德拉的影像处接取，任务提供「奥术微粒」。进城交付给紫罗兰城堡的大法师塞林德拉；若联盟被拦在城外，则在副本入口外交付。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 269127, "Image of Archmage Modera", { xp = 265, rep = { { 2740, 10, "Kirin Tor" } } } },
        { 92456, "A", 24, 33, "Shylamiir", "Stormwind City - Mage Quarter", nil, false, nil, {279835, 279836}, "Gather a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City.", "起始并结束于暴风城法师区的莎拉米尔。注入邪能的花朵出自城内邪能植被，多半在邪能古树一带。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5502, "Shylamiir", { xp = 9400 } },
        { 96986, "H", 24, 33, "Melisara", "Hillsbrad Foothills - Tarren Mill", nil, false, nil, {251963, 251965}, "替塔伦米尔的梅里萨拉，击败达拉然城内的墓穴骑士阿特雷克斯。", "起始并结束于塔伦米尔的梅里萨拉。阿特雷克斯在下水道深处的仪式法阵；他会缴械当前目标 —— 坦克被缴械期间注意减伤。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 2278, "Melisara", { xp = 9400 } },
        { 96988, "H", 24, 33, "Doctor Martin Felben", "Undercity - The Apothecarium", nil, false, nil, {279847, 279848}, "Collect 6 Cracked Sentry Cores from the City of Dalaran for Doctor Martin Felben in Undercity.", "起始并结束于幽暗城的马丁·费尔本。开裂的哨兵核心多半由城内奥术魔像/哨兵造型怪掉落。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 11044, "Doctor Martin Felben", { xp = 9400 } },
        { 92434, "H", 30, 34, "Magus Wordeen Voidglare", "Hillsbrad Foothills - Tarren Mill 61.4,20.8", "喋血街头", false, { 545, 93680 }, nil, "沿洛丹伦湖寻找进入达拉然城的办法。", "在塔伦米尔的大法师沃迪恩·伍德格莱尔处接取（需先完成他发放的其余任务），任务提供「肮脏的钥匙」。沿洛丹伦湖岸找到达拉然城北缘的下水道入口潜入城中，交付给城外的大法师莫德拉的影像。", {{30,1}, {32,2}, {37,3}, {43,4}}, {279469}, nil, 2410, "Magus Wordeen Voidglare", { xp = 270 }},
        { 96984, "H", 24, 33, "Image of Archmage Modera", "Silverpine Forest - 达拉然城副本外", "动乱之源", false, {92434}, {279842, 279843, 279844}, "Recover the Arcane Mote inside the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", "接取在副本外的大法师莫德拉的影像处，交付回塔伦米尔的沃迪恩·伍德格莱尔。部落链：喋血街头（塔伦米尔接取，潜入达拉然，交付在莫德拉的影像处）→ 本任务（进城收集奥术微粒）→ 精明的谈判（回塔伦米尔接，交付给紫罗兰城堡的大法师塞林德拉）。接本任务即自动发放「达拉然下水道钥匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "Image of Archmage Modera", { xp = 9400 } },
        { 97287, "H", 24, 33, "Magus Wordeen Voidglare", "Hillsbrad Foothills - Tarren Mill 61.4,20.8", "精明的谈判", false, {96984}, nil, "带着奥术微粒回到达拉然城，与大法师塞林德拉谈谈。", "在塔伦米尔的大法师沃迪恩·伍德格莱尔处接取，任务提供「奥术微粒」。交付给紫罗兰城堡的大法师塞林德拉；若部落被拦在城外，则在副本入口外交付（即发钥匙的莫德拉的影像处）。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 2410, "Magus Wordeen Voidglare", { xp = 270 }},
        { 96987, "H", 24, 33, "Rexxie Copperclutch", "Alterac Mountains - near the Dalaran sewer entrance", nil, false, nil, { 279845, 279846 }, "Retrieve the Founding of Dalaran from the City of Dalaran and bring it to Rexxie Copperclutch near the sewer entrance.", "发布者雷克西·铜钳守在下水道入口附近。《达拉然的建立》是队伍中每人都能拾取的任务物品 —— 一队人可各自完成。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, nil, "Rexxie Copperclutch", { xp = 9400 } },
    },
    ["gnomeregan"] = {
        { 2843, "H", 20, 35, "Scooty", "Stranglethorn Vale - Booty Bay 27,77", "Gnomer-gooooone!", false, {2842}, {9173}, "Wait while Scooty fixes the goblin teleporter.", "前置可从索维克(奥格瑞玛-荣誉谷 75,25)接。完成后就能使用藏宝海湾的传送器。◎ 哥布林转发器用完可以丢掉，丢了再找斯库提说一声就能再领一个。", {{20,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7853, "Scooty", nil },
        { 2922, "A", 20, 26, "Tinkmaster Overspark", "Ironforge - Tinker Town 69,50", "Tinkmaster Overspark", false, {2923}, nil, "Bring the Storage Core of Techbot to Tinkmaster Overspark in Ironforge.", "前置可从萨尔努修士接(暴风城-教堂广场 51,48)。尖端机器人在进副本前、后门附近。", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {9277}, nil, 7944, "Tinkmaster Overspark", { xp = 2650, money = 2000, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2926, "A", 20, 27, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "Gnogaine", false, {2927}, nil, "Use the Empty Lead Vial to collect Irradiated Dust from Irradiated Invaders or Irradiated Pillagers, fill it, and bring it to Ozzie Togglevolt in Kharanos.", "前置可从诺恩接(铁炉堡-侏儒区 69,50)。取样方法：对活着的辐射入侵者/抢劫者使用空铅瓶。", {{20,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {9284, 9283}, nil, 1268, "Ozzie Togglevolt", { xp = 2200, money = 2200, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2928, "A", 20, 30, "Shoni the Shilent", "Stormwind City - Dwarven District 63,34", nil, false, nil, {9608, 9609, 270045}, "Collect 24 Mechanical Gizzards and bring them to Shoni in Stormwind City.", "All the robots drop gizzards.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9309}, nil, 6579, "Shoni the Shilent", { xp = 2450, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
        { 2953, nil, 25, 30, "Super Cleaner 5200", "Gnomeregan", nil, false, nil, nil, nil, nil, {{25,1}, {26,2}, {28,3}, {33,4}, {40,5}}, { 9308 }, nil, nil, nil, nil },
        { 2962, "A", 20, 30, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "The Only Cure is More Green Glow", false, {2926}, nil, "Collect High-Efficiency Irradiated Dust in Gnomeregan (highly unstable, it decays quickly) and return the Heavy Lead Vial to Ozzie as well.", "Sampling method: use the Heavy Lead Vial on living Irradiated Oozes, Irradiated Creepers or Irradiated Water Elementals.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9365, 9364}, nil, 1268, "Ozzie Togglevolt", { xp = 2450, money = 2500 } },
        { 2904, nil, 24, 30, "Kernobee", "Gnomeregan", nil, true, nil, {9535, 9536, 270042}, "Escort Kernobee to the exit, then report back to Scooty in Booty Bay.", "护送任务。斯库提(荆棘谷-藏宝海湾 27,77)。护送终点是副本正门（送到门口即可，不用穿出去）；小侏儒不会主动引怪，潜行职业全程潜行也能做。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 7850, "Kernobee", { xp = 2450 } },
        { 2924, "A", 24, 30, "Klockmort Spannerspan", "Ironforge - Tinker Town 68,46", "Essential Artificials", false, {2925}, nil, "Collect 12 Basic Modules and bring them to Klockmort Spannerspan in Ironforge.", "前置可从玛希尔接(达纳苏斯-战士区 59,45)。诺莫瑞根的所有敌人都可能掉。", {{24,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9278}, nil, 6169, "Klockmort Spannerspan", { xp = 3050, money = 5500, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2841, "H", 25, 35, "Nogg", "Orgrimmar - Valley of Honor 75,25", nil, false, nil, {9623, 9624, 9625}, "Retrieve the drilling rig blueprints and the combination to Mekgineer's Safe from Gnomeregan and bring them to Nogg in Orgrimmar.", "Mekgineer Thermaplugg is the final boss of Gnomeregan. During the fight, remember to press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, {9153, 9299}, nil, 3412, "Nogg", { xp = 2750, rep = { {76, 100, "Orgrimmar"} } } },
        { 2929, "A", 25, 35, "High Tinker Mekkatorque", "Ironforge - Tinker Town 68,48", nil, false, nil, {9623, 9624, 9625}, "Enter Gnomeregan and kill Mekgineer Thermaplugg, then report to High Tinker Mekkatorque.", "He is the final boss. During the fight, press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7937, "High Tinker Mekkatorque", { xp = 2750, money = 3500, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2930, "A", 25, 30, "Master Mechanic Castpipe", "Ironforge - Tinker Town 69,48", "Data Rescue", false, {2931}, {9605, 9604}, "Bring the Colorful Punch Cards to Master Mechanic Castpipe in Ironforge.", "前置可从加克希姆·尘链接(石爪山脉 59,67)，非必需。读卡接力：白卡出自副本外上层的流动精英，插进副本外的读卡器；每台读卡器都会给出下一台需要的卡，沿途顺路拿科技机器人的脑。", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9316}, nil, 7950, "Master Mechanic Castpipe", { xp = 3650, money = 2500, rep = { {54, 200, "Gnomeregan Exiles"} } } },
        { 2951, nil, 25, 30, "Super Cleaner 5200", "Gnomeregan - Clean Zone", nil, true, nil, nil, "Put grimy items into the Super Cleaner 5200, insert three silver coins to start the machine.", "This quest is repeatable with all \"grimy\" items.", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9308}, nil, nil, nil, { xp = 2450, money = 300 } },
        { 2952, nil, 25, 30, "Super Cleaner 5200", nil, nil, true, {2951}, {9363}, nil, nil, {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, nil, nil, { xp = 2450 } },
        { 2945, nil, 28, 34, "Return of the Ring", "Random drop in Gnomeregan", nil, true, nil, nil, "Figure out how to get the Grimy Ring cleaned.", "Just clean it with the Super Cleaner 5200 — the machine is inside the dungeon.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9326}, nil, nil, nil, { xp = 2700, money = 300 } },
        { 2947, "A", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, nil, nil, "You may keep the ring, or find its owner by the name engraved inside.", "交给塔瓦斯德·基瑟尔(铁炉堡-秘法区 36,3)。奖励戒指属性随机。", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
        { 2949, "H", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, {2945}, nil, "You may keep the ring, or find its owner by the name engraved inside.", "交给诺格(奥格瑞玛-荣誉谷 75,25)。奖励戒指属性随机。", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
    },
    ["razorfen_kraul"] = {
        { 6522, "H", 28, 36, "Starts from the item [Small Scroll]", nil, nil, true, nil, nil, "把「小卷轴」交给幽暗城皇家区的布拉贡·血拳。", "「小卷轴」由剃刀沼泽最终首领卡尔加·刺肋掉落（约 45%），拾取即开启本任务。链的后续在剃刀高地：布拉贡·血拳续接《邪恶的盟友》，杀进本前空地的玛克林大使，头颅交给幽暗城的瓦里玛萨斯。", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 1221, nil, 20, 26, "Mebok Mizzyrix", "The Barrens - Ratchet 62,37", nil, false, nil, {6755}, "Gather the Opened Chest, the Gopher Cane and the \"Gopher Command Manual\"; use the chest in Razorfen Kraul to summon the gopher and make it sniff out the Blueleaf Tubers; finally bring the cane, the chest and 10 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.", "Both the chest and the manual can be found near Mebok Mizzyrix.", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {5876, 5880, 5897, 6684}, nil, 3446, "Mebok Mizzyrix", { xp = 2100, rep = { {470, 100, "Ratchet"} } } },
        { 1701, "A", 20, nil, "Furen Longbeard", "Stormwind City - Dwarven District 64,37", "Fire Hardened Mail", false, {1702}, nil, "Gather the specified materials for Frun Longbeard in Stormwind City.", "Warrior only! The phosphorus comes from Roogug; Scorched Spider Fangs from Wetlands spiders, and Charred and Sleek Chimera Horns from chimera cubs and females in Stonetalon Mountains. Roogug location: take the first left inside the dungeon, follow the curve over the vine bridge — he is right there on the other side.", {{20,1}, {24,2}, {26,3}, {31,4}, {36,5}}, {6838, 6839, 6840, 6841, 6842}, "Warrior", 5413, "Furen Longbeard", { xp = 2300 } },
        { 1838, "H", 20, nil, "Thun'grim Firegaze", "The Barrens 57,30", "Brutal Armor", false, {1825}, nil, "Collect 15 Smoky Iron Ingots, 10 Azurite Powders, 10 Iron Bars and 1 vial of Phlogiston for Thorngrimr.", "Warrior only! Phlogiston comes from Rukhug. After turning in, he will offer the follow-up quest.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {7126, 7127, 3575, 6841, 7587}, "Warrior", 5878, "Thun'grim Firegaze", { xp = 3650 } },
        { 1144, nil, 23, 30, "Willix the Importer", "Razorfen Kraul", nil, true, nil, {6748, 6750, 6749, 274078}, "Escort Willix the Importer out of Razorfen Kraul.", "The escort fails if you get too far ahead of him or fall too far behind. Turn right from the entrance through the boar area to reach Willix — no bosses need to be cleared.", {{22,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 4508, "Willix the Importer", { xp = 7250, rep = { {470, 150, "Ratchet"} } } },
        { 1142, "A", 25, 30, "Heralath Fallowbrook", "Razorfen Kraul", nil, true, nil, {6751, 6752, 270047}, "Retrieve Thalara's Pendant and return it to Thalara Fallowbrook in Darnassus.", "坠饰为随机掉落。交回地点：塔莎拉·静水(达纳苏斯-贸易区 69,67)。", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {5825}, nil, 4510, "Heralath Fallowbrook", { xp = 3050, rep = { {69, 150, "Darnassus"} } } },
        { 1101, "A", 29, 34, "Falfindel Waywarder", "Feralas - Sarannar 89,46", "The Crone of the Kraul", false, {1100}, {4197, 6742, 6725, 274084}, "Bring Calgar Spinegouge's badge to Falfindel Waywarder in Sarannar.", "The badge drops from Calgar Spinegouge.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5792}, nil, 4048, "Falfindel Waywarder", { xp = 3350 } },
        { 1102, "H", 29, 34, "Auld Stonespire", "Thunder Bluff 36,59", nil, false, nil, {4197, 6742, 6725, 274084}, "Bring Calgar Spinegouge's heart to Auld Stonespire in Thunder Bluff.", "Calgar Spinegouge is inside the dungeon.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5793}, nil, 4451, "Auld Stonespire", { xp = 8500, rep = { {81, 200, "Thunder Bluff"} } } },
        { 1109, "H", 30, 33, "Master Apothecary Faranell", "Undercity - The Apothecarium 48,69", nil, false, nil, nil, "Collect a sample of Marsh Bat guano for Master Apothecary Faranell of the Undercity.", "Only the Kraul Bats in the far-west chamber (just before the last boss, Charlga Razorflank) drop the guano — with a very high drop rate — and you must fight through most of the dungeon to reach them.", {{30,2}, {31,3}, {36,4}, {42,5}}, {5801}, nil, 2055, "Master Apothecary Faranell", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 79360, "H", 30, 33, "拉乌·峭壁信使", "Thousand Needles", nil, false, nil, nil, "进入剃刀沼泽，取回野猪人扭曲元素的证据「破烂的笔记」，交给拉乌·峭壁信使。", "萨满职业专属（兽人/牛头人/巨魔）：兽人与巨魔找拉乌·峭壁信使接，牛头人找普拉特·白云；交付随种族对应（拉乌·峭壁信使或捕风者巴斯拉）。萨满图腾任务链第 1 步，后续依次为《仰望天空》《风暴、大地与火焰》《听从我的呼唤》《风暴武器》。", {{30,1}, {31,2}, {36,3}, {42,4}}, {274463}, "Shaman", 4722, "拉乌·峭壁信使", { xp = 6950 } },
        { 96264, "A", 30, 33, "维里克·雷嗥", "阿拉希高地 59.8,27.6", nil, false, nil, nil, "进入剃刀沼泽，取回野猪人扭曲元素的证据「破烂的笔记」，交给阿拉希高地的维里克·雷嗥。", "萨满职业专属（联盟限定）：萨满图腾任务链第 1 步，后续依次为《仰望天空》《风暴、大地与火焰》《听从我的呼唤》《风暴武器》。", {{30,1}, {31,2}, {36,3}, {42,4}}, {274463}, "Shaman", 259023, "维里克·雷嗥", { xp = 6950 } },
    },
    ["sm_graveyard"] = {

        { 1051, "H", 25, 33, "Vorrel Sengutz", "Scarlet Monastery - Graveyard", nil, true, nil, {7750, 4643, 7751}, "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", "戒指在血色修道院墓地区前部的沃瑞尔·森加斯身上；南茜(奥特兰克山脉 31,32)也持有任务相关物品。", {{25,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {5538}, nil, 3981, "Vorrel Sengutz", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
