    ["the_drowned_city"] = {
        { 95775, "H", 30, 40, "肯维雷", "Stranglethorn Vale - 格罗姆高营地 32.3,27.7", nil, false, {95770}, nil, "用兽皮和木炭为沉没之城里的石板制作拓片。", "前置三环都在格罗姆高营地的肯维雷处：暗礁海→古老的古拉巴什传说→定位失落之城。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270308, 270309, 270310, 270311}, nil, 2519, "肯维雷", { xp = 8450, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 95776, "H", 30, 38, "指挥官阿格罗戈什", "Stranglethorn Vale - 格罗姆高营地 32.2,28.9", nil, false, {95773}, {279888, 279889}, "在沉没之城消灭瓦尔塔卡。", "杀怪目标：副本第 2 区首领瓦尔塔卡；前置是格罗姆高营地指挥官阿格罗戈什给的《水中的敌人》。", {{30,1}, {34,2}, {36,3}, {41,4}, {47,5}}, nil, nil, 2464, "指挥官阿格罗戈什", { xp = 9500, rep = { {530, 100, "Darkspear Trolls"}, {76, 100, "Orgrimmar"} } } },
        { 95787, "A", 30, 40, "博学者迪布斯", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95786}, nil, "用兽皮和木炭为沉没之城里的石板制作拓片。", "前置《巨魔巫术》：完成荆棘谷尼麦兹修士的《巨魔巫术》（上交劣质巨魔的神像）后，即可在博学者迪布斯处接取本任务；拓片完成后仍回迪布斯处，由他译好后转交铁炉堡；四块石板分散在副本各段：1 号 Boss 过后下坡左侧、海盗区骷髅堆里、纳迦 Boss 处、尾王处，见到就拓别留到最后。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270308, 270309, 270310, 270311}, nil, 2277, "博学者迪布斯", { xp = 8450, rep = { {72, 100, "Stormwind City"} } } },
        { 95788, "A", 30, 40, "博学者迪布斯", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95786}, nil, "从沉没之城的巨魔身上收集 5 个伊拉莱神像。", "前置《巨魔巫术》：与《就水服下两片》同为博学者迪布斯处的一对任务，完成荆棘谷尼麦兹修士的《巨魔巫术》后即可接取。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270343}, nil, 2277, "博学者迪布斯", { xp = 8450, rep = { {72, 100, "Stormwind City"} } } },
        { 96774, "H", 30, 40, "马祖康", "莫高雷 32.5,20.7", nil, false, nil, nil, "从沉没之城里「最有派头的牧师」身上取回上古古拉巴什神像，交给莫高雷的马祖康。", "起始在副本外(莫高雷 32.5,20.7，疑为雷霆崖)；马祖康，开始并结束于同处；神像由尾王区的不死骨髓掉落（与联盟《上古古拉巴什秘密》同一件物品），沿途祭司也留意。", {{30,1}, {36,2}, {38,3}, {43,4}, {51,5}}, {276894}, nil, 264074, "马祖康", { xp = 8800, money = 10000, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 95789, nil, 34, 40, "Krazek", "Stranglethorn Vale - Booty Bay 27.0,77.2", nil, false, nil, {279882, 279930}, "收集 10 个注入巫毒的神器，交给藏宝海湾的克拉兹克。", "起始在副本外（藏宝海湾）；神器由副本内盐水先知施法者掉落，清怪时留意拾取；两个阵营都可接。", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270333}, nil, 773, "Krazek", { xp = 10450, rep = { {21, 100, "Booty Bay"}, {470, 50, "Ratchet"}, {369, 50, "Gadgetzan"} } }},
        { 95791, nil, 34, 40, "Krazek", "Stranglethorn Vale - Booty Bay 27.0,77.2", nil, false, nil, {279883, 279884}, "消灭德雷德莱斯船长和盐水先知验尸官，回藏宝海湾向克拉兹克复命。", "杀怪目标：船长是副本首领之一；验尸官沿路成群，一趟顺路即可；两个阵营都可接。", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 773, "Krazek", { xp = 10450, rep = { {21, 100, "Booty Bay"}, {369, 50, "Gadgetzan"}, {577, 50, "Everlook"} } }},
        { 97130, "A", 34, 40, "大法师提迈尔", "Alterac Mountains 15.4,73.8", nil, false, nil, nil, "取回上古古拉巴什神像，交给肯瑞托的大法师提迈尔。", "起始在副本外（奥特兰克山脉）；神像由不死骨髓一战掉落，与部落的古拉巴什神像任务共用目标物品。", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {276894}, nil, 31439, "大法师提迈尔", { xp = 10450, rep = { {2740, 300, "Kirin Tor"}, {72, 150, "Stormwind City"} } }},
        { 95798, "A", 30, 40, "博学者迪布斯", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95788}, {279879, 279878}, "把伊拉莱神像带给达拉然的魔杖商安布拉·卡达布拉。", "前置《沉没之城的魔法》：《沉没之城的魔法》收集的伊拉莱神像正是本任务的交付物，接取人即前者的交付 NPC；不可分享。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270343}, nil, 2277, "博学者迪布斯", { xp = 2350, rep = { {72, 75, "Stormwind City"} } } },
        { 95799, "A", 30, 40, "博学者迪布斯", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95787}, {279880, 279881}, "把博学者迪布斯译好的《伊拉莱传说》送到铁炉堡，交给史学家卡尼克。", "前置《就水服下两片》：拓片任务的成果（译好的伊拉莱传说）即本任务交付物；接取人博学者迪布斯（探险者协会），交付人史学家卡尼克在铁炉堡。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {272124}, nil, 2277, "博学者迪布斯", { xp = 2350, rep = { {72, 75, "Stormwind City"}, {47, 50, "Ironforge"} } } },
    },
