    ["dire_maul_west"] = {
        { 7481, "H", 54, nil, "Sage Korolusk", "Feralas - Camp Mojache 74,43", nil, false, nil, nil, "Find Kariel Winthalus in Dire Maul, then report what you have learned to Sage Korolusk at Camp Mojache.", "Kariel Winthalus is in the Dire Maul West library. The skeleton is in the center of the library, next to Lorekeeper Lydros.", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14373, "Sage Korolusk", { xp = 19700 } },
        { 7482, "A", 54, nil, "Scholar Runethorn", "Feralas - Feathermoon Stronghold 31,43", nil, false, nil, nil, "Find Kariel Winthalus in Dire Maul, then report what you have learned to Scholar Runethorn at Feathermoon Stronghold.", "Kariel Winthalus is in the Dire Maul West library. His skeleton is in the center of the library, next to Lorekeeper Lydros.", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14374, "Scholar Runethorn", { xp = 19700 } },
        { 7483, nil, 54, nil, "Lorekeeper Lydros", "Dire Maul: West, the Library", nil, false, {7482}, { 18329 }, "Hand the Libram of Protection, 1 Primal Black Diamond, 2 Large Brilliant Shards and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul for a Protection Elixir.", "No prerequisite, but the \"Elven Legends\" quest must be completed first. The libram drops randomly in Dire Maul and is tradeable on the auction house. Frayed Abomination Stitching drops randomly from Swallower Ramsden, Patched Abominations, Venom Belchers and Gall Sprayers in Stratholme, picked up bound.", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18332, 18335, 14344, 12938}, nil, 14368, nil, { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } }},
        { 7484, nil, 54, nil, "The Tome of Defense", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, {7482}, { 18330 }, "Turn this tome in to its owner.", "Warrior class trinket quest. Bring it to Lorekeeper Kildas (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18333, 18335, 14344, 12753}, nil, 14368, "Lorekeeper Lydros", { xp = 3300, rep = { { 809, 200, "Shen'dralar" } } } },
