    [2948] = { lv = 28, lvStd = 31, npc = "Talvash del Kissel", npcid = 6826, zone = "Ironforge", obj = "将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。", text = "塔瓦斯德·基瑟尔在铁炉堡（36.0,3.4）。" },
    [2953] = { lv = 25, lvStd = 30, npc = "Super Cleaner 5200", zone = "Gnomeregan", obj = "超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动！", text = "超级清洁器5200型在诺莫瑞根。" },
    [3369] = { lv = 10, lvStd = 21, npc = "菲拉·古风", npcid = 8418, zone = "The Barrens", obj = "把噩梦碎片交给长者高地的哈缪尔·符文图腾。", text = "菲拉·古风在贫瘠之地（48.2,32.8）。完成后去找大德鲁伊哈缪尔·符文图腾（雷霆崖）。" },
    [3375] = { lv = 37, lvStd = 38, npc = "Talvash del Kissel", npcid = 6826, zone = "Ironforge", obj = "把一瓶法力药水、一块煤和一瓶蜂蜜酒送到铁炉堡的塔瓦斯德·基瑟尔那里，用以换取塔瓦斯德的占卜之瓶。", text = "塔瓦斯德·基瑟尔在铁炉堡（36.0,3.4）。" },
    [4148] = { lv = 47, lvStd = 49, npc = "Larion", npcid = 9118, zone = "Un'Goro Crater", obj = "收集血瓣花苗，交给安戈洛环形山的拉瑞安。", text = "拉瑞安在安戈洛环形山（45.4,8.4）。" },
    [4295] = { lv = 1, lvStd = 1, npc = "罗克诺特下士", npcid = 9503, zone = "Blackrock Depths", obj = "哦，酒！为了黑铁矮人的酒，我甚至愿意去杀人！快点，我的酒劲正在消退！我的视线越来越模糊了……你看上去越来越像上个星期我干掉的那个&lt;race&gt;了！", text = "罗克诺特下士在黑石深渊。" },
    [5063] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。完成后去找玛雷弗斯·暗锤（冬泉谷）。" },
    [5067] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。" },
    [5068] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。完成后去找玛雷弗斯·暗锤（冬泉谷）。" },
    [5122] = { lv = 55, lvStd = 56, npc = "Aurius", npcid = 10917, zone = "Stratholme", obj = "取回信仰奖章，交给斯坦索姆的奥里克斯。", text = "奥里克斯在斯坦索姆。" },
    [5265] = { lv = 55, lvStd = 56, npc = "玛克斯韦尔·泰罗索斯男爵", npcid = 11034, zone = "Eastern Plaguelands", obj = "打开银色黎明宝箱，拿取你应得的奖励。", text = "玛克斯韦尔·泰罗索斯男爵在东瘟疫之地（81.4,58.0）。" },
    [5342] = { lv = 52, lvStd = 56, npc = "Alexi Barov", npcid = 11022, zone = "Tirisfal Glades", obj = "到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。", text = "阿莱克斯·巴罗夫在提瑞斯法林地（83.0,71.4）。" },
    [5344] = { lv = 52, lvStd = 56, npc = "Weldon Barov", npcid = 11023, zone = "Western Plaguelands", obj = "去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的脑袋交给维尔顿·巴罗夫。", text = "维尔顿·巴罗夫在西瘟疫之地（43.4,83.4）。" },
    [6804] = { lv = 55, lvStd = 59, npc = "Duke Hydraxis", npcid = 13278, zone = "Azshara", obj = "对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。", text = "海达克西斯公爵在艾萨拉（79.2,73.4）。" },
    [7483] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7482}, obj = "将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7484] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7482}, obj = "将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 3300, rep = { { 809, 200, "Shen'dralar" } } } },
    [7485] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7482}, obj = "将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7509] = { lv = 60, lvStd = 63, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", obj = "你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。", text = "博学者莱德罗斯在厄运之槌。" },
    [7638] = { lv = 60, lvStd = 63, npc = "Duthorian Rall", npcid = 6171, zone = "Stormwind City", obj = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。", text = "达索瑞恩·拉尔在暴风城（39.4,30.6）。完成后去找格雷森·沙东布瑞克公爵（暴风城）。" },
    [8996] = { lv = 58, lvStd = 63, npc = "瓦塔拉克公爵之魂", npcid = 16073, zone = "Dire Maul: North", obj = "回到黑石山的伯德雷那里去，把召唤火盆交给他。", text = "瓦塔拉克公爵之魂在厄运之槌 北。完成后去找伯德雷。" },
    [92345] = { lv = 45, lvStd = 55, npc = "指挥官真歌", npcid = 239822, side = "A", zone = "Azshara", obj = "去艾萨拉找指挥官真歌问清诺达希尔之下的情况，再去尘泥沼泽向玛斯雷·驭熊者回报。", text = "诺达希尔之下系列（联盟）第一环：指挥官真歌在艾萨拉（11.8,78.2），问完后去尘泥沼泽找玛斯雷·驭熊者（34.8,7.4）。" },
    [92346] = { lv = 45, lvStd = 55, npc = "杰迪加", npcid = 8587, side = "H", zone = "Azshara", obj = "去艾萨拉找杰迪加问清诺达希尔之下的情况，再去雷霆崖向纳拉·蛮鬃回报。", text = "诺达希尔之下系列（部落）第一环：杰迪加在艾萨拉（22.4,51.4），问完后去雷霆崖找纳拉·蛮鬃（75.2,30.4）。" },
