    [94997] = { lv = 38, lvStd = 42, npc = "里夫坦中士", npcid = 258023, side = "A", zone = "河林", obj = "收集被诅咒的遗物背包，把它交给法霍尔德堡的艾什·安伯霍尔。", text = "河林引导系列（三环）的第二环：里夫坦中士在河林（30.6,49.0）接取；凑齐被诅咒的遗物背包后回法霍尔德堡交给艾什·安伯霍尔（66.6,81.0）。", gains = { xp = 3450, money = 5500 } },
    [95454] = { lv = 48, lvStd = 53, side = "H", zone = "Prison of Alcaz", obj = "查明瓦里安·乌瑞恩的下落，并读一读地上的字条。", text = "奥卡兹监狱部落引导链的第一环：进奥卡兹监狱找到瓦里安·乌瑞恩，读地上的字条；后续再把消息带回奥格瑞玛给萨尔。", gains = { xp = 12100, rep = { { 76, 100, "Orgrimmar" } } } },
    [96775] = { lv = 42, lvStd = 46, npc = "马祖康", npcid = 264074, side = "H", zone = "莫高雷", obj = "深入祖尔法拉克，消灭巫医祖穆拉恩，把他的头颅完整地带回来。", text = "接取与上交都是莫高雷的 马祖康（32.5,20.7）：先接任务，再进祖尔法拉克杀巫医祖穆拉恩拿头颅回来交。", gains = { xp = 10100, money = 6500 } },
    [96776] = { lv = 43, lvStd = 51, npc = "奥拉娜·闪蹄", npcid = 268557, side = "H", zone = "莫高雷", obj = "从玛拉顿取回名为安瑟的光辉的水晶，带回给奥拉娜·闪蹄。", text = "奥拉娜·闪蹄在莫高雷（32.6,24.0）接取；安瑟的光辉是玛拉顿内的水晶，拿到后回去交给她。", gains = { xp = 11900, money = 7500 } },
    [97197] = { lv = 46, lvStd = 55, npc = "阿拉娜·风暴行者", npcid = 259119, side = "H", zone = "莫高雷", obj = "从黑石深渊取回火焰之地碎片，带回给阿拉娜·风暴行者。", text = "阿拉娜·风暴行者在莫高雷（33.4,22.4）接取；火焰之地碎片掉自黑石深渊，拿到后回去交给她。", gains = { xp = 14800, money = 8500 } },
    [92914] = { lv = 35, lvStd = 43, nm = "奇怪的水晶塔", npc = "辛德拉水晶塔（43.8,34.3）", zone = "Shen'dralar", si = true, obj = "探索辛德拉，设法寻找与你所见相似的其他水晶塔。", text = "辛德拉线的链头：在野外的水晶塔旁拾取开启（物件起始），就地交给神殿的莫丹特·永影（35.1,46.4）。", gains = { xp = 3600 } },
    [96010] = { lv = 35, lvStd = 41, nm = "水晶塔碎片", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 92914 }, obj = "取回盛格拉斯村和吉尔吉斯村严密看守的水晶塔碎片与残片，交给莫丹特·永影。", text = "碎片被半人马当战利品带回盛格拉斯、吉尔吉斯两个村子，两处都有守卫看着；取齐后回神殿交给莫丹特·永影。", gains = { xp = 2450 } },
    [96018] = { lv = 35, lvStd = 43, nm = "为晶塔供能", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 96010 }, obj = "从辛德拉神殿内取得法力过滤网，用它收集远古魔力水晶，为水晶塔充能后向莫丹特·永影复命。", text = "法力过滤网借自神殿，守卫不会客气；收满漂浮的魔力水晶后给两座水晶塔充能，再回莫丹特处复命。", gains = { xp = 3600 } },
    [93016] = { lv = 35, lvStd = 43, nm = "简短的历史课", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 96018 }, obj = "与辛德拉的莫丹特·永影交谈，了解你修复的那些水晶的信息。", text = "纯对话环：回神殿找莫丹特·永影听完辛德拉的来历即可，交完紧接着《会见魔导师》。", gains = { xp = 360 } },
    [93394] = { lv = 35, lvStd = 43, nm = "会见魔导师", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 93016 }, obj = "在辛德拉神殿内找到魔导师基兰迪斯。", text = "进神殿往深处走，找魔导师基兰迪斯（47.4,76.2）对话即可；在神殿里别乱开怪。", gains = { xp = 360 } },
    [93341] = { lv = 35, lvStd = 43, nm = "荒弃花园", npc = "米瑟拉（53.2,75.9）", npcid = 254578, zone = "Shen'dralar", pre = { 93394 }, obj = "调查辛德拉附近的荒弃花园，然后回到附近神殿找米瑟拉复命。", text = "米瑟拉在神殿外（53.2,75.9）；去东南边的荒弃花园查一圈再回来复命，交完就能接《林中传言》。", gains = { xp = 1800 } },
